<!doctype html><html><head><meta charset="utf-8"><title>{{ $order->order_number }}</title><style>body{font-family:Arial,sans-serif;color:#1e293b;margin:36px}.head{display:flex;justify-content:space-between;border-bottom:2px solid #128c7e;padding-bottom:16px;margin-bottom:22px}h1{margin:0;color:#128c7e}table{border-collapse:collapse;width:100%;margin-top:20px}th,td{padding:11px;border-bottom:1px solid #e2e8f0;text-align:left}th{text-transform:uppercase;font-size:12px;background:#f8fafc;color:#64748b}.right{text-align:right}.total{font-size:18px;font-weight:bold}.muted{color:#64748b;font-size:13px}</style></head><body><div class="head"><div><h1>Store Order Bill</h1><p class="muted">{{ $order->order_number }} · Delivered</p></div><div class="right"><strong>{{ optional($order->store)->name }}</strong><br><span class="muted">{{ optional($order->store)->address }}</span></div></div><p><strong>Created by:</strong> {{ optional($order->posUser)->name }}<br><strong>Date:</strong> {{ $order->created_at->format('d M Y, h:i A') }}</p><table><thead><tr><th>Product</th><th class="right">Price</th><th class="right">Qty</th><th class="right">Total</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->product_name }}</td><td class="right">₹{{ number_format($item->price, 2) }}</td><td class="right">{{ $item->quantity }}</td><td class="right">₹{{ number_format($item->total, 2) }}</td></tr>@endforeach</tbody><tfoot><tr><td colspan="3" class="right total">Grand Total</td><td class="right total">₹{{ number_format($order->grand_total, 2) }}</td></tr></tfoot></table></body></html>
